module pattern_matcher(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] word0, word1, word2, word3,\n    input wire [7:0] word4, word5, word6, word7,\n    input wire [3:0] len0, len1, len2, len3,\n    input wire [3:0] len4, len5, len6, len7,\n    input wire [7:0] pat0, pat1, pat2, pat3,\n    input wire [7:0] pat4, pat5, pat6, pat7,\n    input wire [3:0] star_pos,\n    input wire [3:0] pattern_len,\n    input wire [3:0] num_words,\n    output reg [7:0] count,\n    output reg done\n);\n\n    localparam [2:0] IDLE = 3'b000;\n    localparam [2:0] CHECK_LEN = 3'b001;\n    localparam [2:0] CHECK_PREFIX = 3'b010;\n    localparam [2:0] CHECK_SUFFIX = 3'b011;\n    localparam [2:0] COUNT = 3'b100;\n    localparam [2:0] NEXT_WORD = 3'b101;\n    localparam [2:0] DONE = 3'b110;\n\n    reg [2:0] state;\n    reg [3:0] word_idx;\n    reg [3:0] char_idx;\n    reg match_flag;\n    reg [3:0] prefix_len;\n    reg [3:0] suffix_len;\n    reg [3:0] required_len;\n    reg [7:0] current_word_char;\n    reg [3:0] current_word_len;\n    reg [7:0] current_pat_char;\n\n    always @(*) begin\n        case(word_idx)\n            4'd0: begin current_word_char = word0; current_word_len = len0; end\n            4'd1: begin current_word_char = word1; current_word_len = len1; end\n            4'd2: begin current_word_char = word2; current_word_len = len2; end\n            4'd3: begin current_word_char = word3; current_word_len = len3; end\n            4'd4: begin current_word_char = word4; current_word_len = len4; end\n            4'd5: begin current_word_char = word5; current_word_len = len5; end\n            4'd6: begin current_word_char = word6; current_word_len = len6; end\n            4'd7: begin current_word_char = word7; current_word_len = len7; end\n            default: begin current_word_char = 8'd0; current_word_len = 4'd0; end\n        endcase\n    end\n\n    always @(*) begin\n        case(char_idx)\n            4'd0: current_pat_char = pat0;\n            4'd1: current_pat_char = pat1;\n            4'd2: current_pat_char = pat2;\n            4'd3: current_pat_char = pat3;\n            4'd4: current_pat_char = pat4;\n            4'd5: current_pat_char = pat5;\n            4'd6: current_pat_char = pat6;\n            4'd7: current_pat_char = pat7;\n            default: current_pat_char = 8'd0;\n        endcase\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            count <= 8'd0;\n            done <= 1'b0;\n            word_idx <= 4'd0;\n            char_idx <= 4'd0;\n            match_flag <= 1'b0;\n            prefix_len <= 4'd0;\n            suffix_len <= 4'd0;\n            required_len <= 4'd0;\n        end else begin\n            case(state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        prefix_len <= star_pos;\n                        suffix_len <= pattern_len - star_pos - 4'd1;\n                        required_len <= pattern_len - 4'd1;\n                        word_idx <= 4'd0;\n                        count <= 8'd0;\n                        state <= CHECK_LEN;\n                    end\n                end\n                \n                CHECK_LEN: begin\n                    if (word_idx >= num_words) begin\n                        state <= DONE;\n                    end else if (current_word_len >= required_len) begin\n                        char_idx <= 4'd0;\n                        match_flag <= 1'b1;\n                        state <= CHECK_PREFIX;\n                    end else begin\n                        state <= NEXT_WORD;\n                    end\n                end\n                \n                CHECK_PREFIX: begin\n                    if (char_idx >= prefix_len) begin\n                        char_idx <= 4'd0;\n                        state <= CHECK_SUFFIX;\n                    end else begin\n                        if (current_word_char != current_pat_char) begin\n                            match_flag <= 1'b0;\n                            state <= NEXT_WORD;\n                        end else begin\n                            char_idx <= char_idx + 4'd1;\n                        end\n                    end\n                end\n                \n                CHECK_SUFFIX: begin\n                    if (char_idx >= suffix_len) begin\n                        if (match_flag) begin\n                            state <= COUNT;\n                        end else begin\n                            state <= NEXT_WORD;\n                        end\n                    end else begin\n                        char_idx <= char_idx + 4'd1;\n                    end\n                end\n                \n                COUNT: begin\n                    count <= count + 8'd1;\n                    state <= NEXT_WORD;\n                end\n                \n                NEXT_WORD: begin\n                    word_idx <= word_idx + 4'd1;\n                    state <= CHECK_LEN;\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule